// ── /userstore/<kind> — per-account chart state (2026-10-06) ──────────────
// GET  /userstore/chart-watchlist            → {doc, updated_at} | {doc:null}
// PUT  /userstore/chart-watchlist            ← {doc, updated_at}  (≤ 3 MB)
// GET  /userstore/chart-files                → index of imported files
// PUT  /userstore/chart-files                ← index (≤ 300 KB)
// GET  /userstore/chart-file?id=<id>         → one imported file (rows)
// PUT  /userstore/chart-file?id=<id>         ← file (≤ 6 MB) or {"delete":true}
// The account id comes only from the verified Supabase bearer token; no path or body identity is read.
if (url.pathname.startsWith("/userstore/")) {
  const kind = url.pathname.slice("/userstore/".length);
  const LIMITS = { "chart-watchlist": 3000000, "chart-files": 300000, "chart-file": 6000000 };
  if (!LIMITS[kind]) return jsonResp({ error: "unknown store" }, 404);
  if (request.method !== "GET" && request.method !== "PUT") return jsonResp({ error: "method not allowed" }, 405);
  if (!env.USER_DATA) return jsonResp({ error: "user store unavailable" }, 503);
  const storeUid = await verifySupabaseUser();
  if (!storeUid) return jsonResp({ error: "auth required" }, 401);
  let key = "userstore:" + storeUid + ":" + kind;
  if (kind === "chart-file") {
    const fid = String(url.searchParams.get("id") || "");
    if (!/^[A-Za-z0-9_.:-]{1,80}$/.test(fid)) return jsonResp({ error: "invalid file id" }, 400);
    key += ":" + fid;
  }
  const priv = { "Content-Type": "application/json", "Cache-Control": "private, no-store", Vary: "Authorization", ...corsHeaders() };
  if (request.method === "GET") {
    const raw = await env.USER_DATA.get(key);
    return new Response(raw || JSON.stringify({ doc: null }), { status: 200, headers: priv });
  }
  const raw = await boundedBody(request, LIMITS[kind]);
  if (raw === null) return jsonResp({ error: "payload too large", limit: LIMITS[kind] }, 413);
  let body; try { body = JSON.parse(raw); } catch (_) { return jsonResp({ error: "invalid json" }, 400); }
  if (!body || typeof body !== "object" || Array.isArray(body)) return jsonResp({ error: "store body must be an object" }, 400);
  if (kind === "chart-file" && body.delete === true) {
    await env.USER_DATA.delete(key);
    return new Response(JSON.stringify({ ok: true, deleted: true }), { headers: priv });
  }
  if (!("doc" in body)) return jsonResp({ error: "send {doc, updated_at}" }, 400);
  const stamp = Number(body.updated_at) || Date.now();
  await env.USER_DATA.put(key, JSON.stringify({ doc: body.doc, updated_at: stamp, saved_at: Date.now() }));
  return new Response(JSON.stringify({ ok: true, updated_at: stamp, bytes: raw.length }), { headers: priv });
}

