// GET /fmp?ep=<allowlisted>&symbol=AAPL[&period=annual|quarter][&limit=N][&year=&quarter=]
// Read-through for the symbol page; only the endpoints listed here, symbol validated, 6h edge cache.
if (url.pathname === "/fmp") {
  const EPS = {
    "income-statement": 1, "balance-sheet-statement": 1, "cash-flow-statement": 1, "ratios": 1, "key-metrics": 1,
    "profile": 0, "etf/info": 0, "etf/holdings": 0, "etf/sector-weightings": 0, "etf/country-weightings": 0,
    "etf/asset-exposure": 0, "dividends": 0, "institutional-ownership/symbol-positions-summary": 2,
    "shares-float": 0, "grades-consensus": 0, "ratios-ttm": 0, "key-metrics-ttm": 0, "earnings": 0,
  };
  const ep = String(url.searchParams.get("ep") || "");
  const sym = String(url.searchParams.get("symbol") || "").trim().toUpperCase();
  if (!(ep in EPS)) return jsonResp({ error: "endpoint not allowed" }, 400);
  if (!/^[A-Z0-9.\-^]{1,15}$/.test(sym)) return jsonResp({ error: "invalid symbol" }, 400);
  const qs = new URLSearchParams({ symbol: sym });
  if (EPS[ep] === 1) {
    const per = url.searchParams.get("period") === "quarter" ? "quarter" : "annual";
    qs.set("period", per); qs.set("limit", String(Math.max(1, Math.min(40, Number(url.searchParams.get("limit")) || 10))));
  }
  if (EPS[ep] === 2) {
    const y = Number(url.searchParams.get("year")), q = Number(url.searchParams.get("quarter"));
    if (y >= 2000 && y <= 2100) qs.set("year", String(y));
    if (q >= 1 && q <= 4) qs.set("quarter", String(q));
  }
  if (ep === "earnings") qs.set("limit", "12");
  const ck = new Request("https://fmp.cache/" + ep + "?" + qs.toString(), { method: "GET" });
  const cache = caches.default;
  const hit = await cache.match(ck);
  if (hit) return new Response(await hit.text(), { headers: { "Content-Type": "application/json", "X-Cache": "HIT", ...corsHeaders() } });
  qs.set("apikey", env.FMP_KEY || "");
  let status = 502, text = "";
  try {
    const r = await fetch("https://financialmodelingprep.com/stable/" + ep + "?" + qs.toString(), { cf: { cacheTtl: 3600 } });
    status = r.status; text = await r.text();
  } catch (e) { return jsonResp({ error: "provider fetch failed", detail: String(e).slice(0, 120) }, 502); }
  let data = null; try { data = JSON.parse(text); } catch (_) {}
  if (status !== 200 || data === null) {
    const msg = (data && (data["Error Message"] || data.error || data.message)) || text.slice(0, 160);
    return jsonResp({ error: "provider " + status, detail: String(msg).replace(/apikey=[^&\s"]+/gi, "apikey=***").slice(0, 200), ep, symbol: sym }, status === 200 ? 502 : (status >= 400 && status < 500 ? 424 : 502));
  }
  const out = JSON.stringify({ ep, symbol: sym, source: "Financial Modeling Prep /stable/" + ep, fetched_at: new Date().toISOString(), data });
  ctx.waitUntil(cache.put(ck, new Response(out, { headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=21600" } })));
  return new Response(out, { headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=3600", "X-Cache": "MISS", ...corsHeaders() } });
}

